// Per-run performance table: everything about latency and outcomes in tables.
const inp = $('Input').item.json;
const slugs = {};
for (const c of $('Load Case Names').all()) { const j = c.json; if (j && j.id) slugs[j.id] = j.slug; }
const rows = $input.all().map(i => i.json).filter(r => r && r.run_id === inp.run_id);
const seen = new Set();
const cases = [];
for (const r of rows) { if (!r.case_id || seen.has(r.case_id)) continue; seen.add(r.case_id); cases.push(r); }
const cell = t => String(t).replace(/\|/g, '\\|').replace(/\n+/g, ' ');
const durs = cases.map(c => (typeof c.duration_ms === 'number' ? c.duration_ms : null)).filter(v => v !== null).sort((a, b) => a - b);
const q = p => durs.length ? Math.round(durs[Math.min(durs.length - 1, Math.round(p * (durs.length - 1)))] / 1000) : null;
const sum = arr => arr.reduce((a, b) => a + b, 0);
const passed = cases.filter(c => c.status === 'pass').length;
const failed = cases.filter(c => c.status === 'fail').length;
const errored = cases.filter(c => c.status === 'error').length;
const tokTotal = sum(cases.map(c => (c.usage && typeof c.usage.totalTokens === 'number') ? c.usage.totalTokens : 0));
const times = cases.map(c => new Date(c.created_at).getTime()).sort((a, b) => a - b);
let wallS = null;
if (times.length > 1) {
  const firstLanded = cases.reduce((best, c) => (new Date(c.created_at).getTime() < new Date(best.created_at).getTime() ? c : best), cases[0]);
  const firstStart = new Date(firstLanded.created_at).getTime() - (typeof firstLanded.duration_ms === 'number' ? firstLanded.duration_ms : 0);
  wallS = Math.round((times[times.length - 1] - firstStart) / 1000);
}
// Expected vs landed: the runner passes the dispatched slug list so a
// timed-out run names exactly which cases never landed.
const expected = String(inp.expected_slugs ?? '').split(',').map(s => s.trim()).filter(Boolean);
const landedSlugs = new Set(cases.map(c => c.case_slug || slugs[c.case_id] || c.case_id));
const missing = expected.filter(s => !landedSlugs.has(s));
const fmtS = v => (v == null ? '\u2014' : v + 's');
const lines = [];
lines.push('## \ud83d\udcca ' + inp.label + ' \u2014 ' + inp.run_id, '');
lines.push('| Metric | Value |');
lines.push('| --- | --- |');
if (expected.length) {
  lines.push('| Run status | ' + (missing.length === 0 ? '\u2705 complete \u2014 ' + cases.length + '/' + expected.length + ' landed' : '\u26a0\ufe0f INCOMPLETE \u2014 ' + cases.length + '/' + expected.length + ' landed') + ' |');
}
lines.push('| Cases landed | ' + cases.length + ' |');
lines.push('| \u2705 Pass / \u274c Fail / \ud83d\udca5 Error | ' + passed + ' / ' + failed + ' / ' + errored + ' |');
lines.push('| Pass rate | ' + (cases.length ? ((passed / cases.length) * 100).toFixed(1) + '%' : '\u2014') + ' |');
if (durs.length) {
  lines.push('| Case duration \u2014 median | ' + fmtS(q(0.5)) + ' |');
  lines.push('| Case duration \u2014 mean | ' + Math.round(sum(durs) / durs.length / 1000) + 's |');
  lines.push('| Case duration \u2014 p90 | ' + fmtS(q(0.9)) + ' |');
  lines.push('| Case duration \u2014 max | ' + fmtS(q(1)) + ' |');
  lines.push('| Total compute | ' + Math.round(sum(durs) / 1000) + 's |');
}
if (wallS) lines.push('| Wall clock (first start \u2192 last landed) | ' + wallS + 's |');
if (tokTotal) lines.push('| Total tokens | ' + tokTotal.toLocaleString() + ' |');
if (missing.length) {
  lines.push('| \u23f3 Never landed (timed out / still running) | ' + missing.map(s => '`' + s + '`').join(', ') + ' |');
}
lines.push('', '### Cases by duration', '');
lines.push('| Case | Status | Duration | Tokens | Tools |');
lines.push('| --- | --- | --- | --- | --- |');
const sorted = cases.slice().sort((a, b) => (b.duration_ms || 0) - (a.duration_ms || 0));
for (const c of sorted) {
  const slug = c.case_slug || slugs[c.case_id] || c.case_id;
  const st = c.status === 'pass' ? '\u2705 pass' : (c.status === 'fail' ? '\u274c fail' : '\ud83d\udca5 ' + c.status);
  const dur = typeof c.duration_ms === 'number' ? Math.round(c.duration_ms / 1000) + 's' : '\u2014';
  const tok = (c.usage && c.usage.totalTokens) ? Number(c.usage.totalTokens).toLocaleString() : '\u2014';
  let tools = c.called_tools;
  if (typeof tools === 'string') { try { tools = JSON.parse(tools); } catch (e) { tools = [tools]; } }
  const toolsStr = Array.isArray(tools) ? tools.join(', ') : '\u2014';
  lines.push('| `' + cell(slug) + '` | ' + st + ' | ' + dur + ' | ' + tok + ' | ' + cell(toolsStr) + ' |');
}
lines.push('', '_Generated ' + new Date().toISOString() + '_');
return [{ json: { markdown: lines.join('\n') } }];

// Build Slack Block Kit markdown blocks from the Summary node's markdown output.
// Splits long text across multiple mrkdwn blocks (3,000-char limit each),
// up to ~90KB total serialized JSON payload to stay within Slack API limits.
// Splits on newlines where possible. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).

const PER_BLOCK = 2900;  // leave margin under Slack's 3000-char limit
const MAX_BLOCKS = 50;   // hard cap: Slack max 50 blocks
const MAX_PAYLOAD_BYTES = 90000;  // ~90KB budget for serialized { blocks: [...] }
const TRUNCATION_NOTE = '\n\n_… (truncated: response too long for a single Slack message)_';

let text = $json.markdown ?? '';
const fullText = text;  // preserve original for downstream use

// --- Helper: estimate serialized size of a blocks array ---
function estimatePayloadSize(blocksArr) {
  // Serialize just the blocks array; the outer { "blocks": [...] } wrapper adds ~15 chars
  return JSON.stringify(blocksArr).length + 20;
}

// --- Split text into chunks ---
function splitIntoChunks(str, chunkSize, maxBlocks, maxBytes) {
  const chunks = [];
  const trialBlocks = [];

  while (str.length > 0 && chunks.length < maxBlocks) {
    if (str.length <= chunkSize) {
      chunks.push(str);
      trialBlocks.push({ type: 'markdown', text: str });
      if (estimatePayloadSize(trialBlocks) > maxBytes) {
        const removed = chunks.pop();
        trialBlocks.pop();
        const remaining = maxBytes - estimatePayloadSize(trialBlocks);
        const maxTextLen = Math.max(0, remaining - 60);
        if (maxTextLen > 50) {
          chunks.push(removed.slice(0, maxTextLen) + TRUNCATION_NOTE);
        }
      }
      break;
    }

    // Try to find last newline within the chunk boundary
    const sliceTarget = str.slice(0, chunkSize);
    const lastNewline = sliceTarget.lastIndexOf('\n');
    let chunk;
    if (lastNewline > chunkSize - 500) {
      chunk = str.slice(0, lastNewline);
      str = str.slice(lastNewline + 1);
    } else {
      chunk = sliceTarget;
      str = str.slice(chunkSize);
    }

    const tentativeBlocks = [...trialBlocks, { type: 'markdown', text: chunk }];
    if (estimatePayloadSize(tentativeBlocks) > maxBytes) {
      const remaining = maxBytes - estimatePayloadSize(trialBlocks);
      const maxTextLen = Math.max(0, remaining - 60);
      if (maxTextLen > 50) {
        chunks.push(chunk.slice(0, maxTextLen) + TRUNCATION_NOTE);
      }
      break;
    }

    chunks.push(chunk);
    trialBlocks.push({ type: 'markdown', text: chunk });
  }

  if (str.length > 0 && chunks.length === maxBlocks) {
    chunks[chunks.length - 1] = chunks[chunks.length - 1].replace(/\n*$/, '') + TRUNCATION_NOTE;
  }

  return chunks;
}

const chunks = splitIntoChunks(text, PER_BLOCK, MAX_BLOCKS, MAX_PAYLOAD_BYTES);
const blocks = chunks.map(t => ({ type: 'markdown', text: t }));
const content = { blocks };

return [{ json: { blocksJson: JSON.stringify(content), output: fullText } }];

// Group the formatted blocks into message-sized chunks so no single Slack
// message exceeds Slack's cumulative block-text limit (~13k chars, undocumented —
// see slackapi/bolt-js#2509). Emits one item per message; Send a message then posts
// one message per item. Ported from the "Slack" workflow (9UJFDlOnoxSzFCS1).
const MSG_BUDGET = 8000; // chars of block text per message, safe margin under ~13k

const blocksJson = $('format').first().json.blocksJson;

let blocks;
try {
  blocks = JSON.parse(blocksJson).blocks;
  if (!Array.isArray(blocks) || blocks.length === 0) throw new Error('no blocks');
} catch (e) {
  // Fall back to previous single-message behaviour if parsing fails
  return [{ json: { blocksJson, part: 1, totalParts: 1 } }];
}

const messages = [];
let current = [];
let currentLen = 0;

for (const block of blocks) {
  const len = (block.text || '').length;
  if (current.length > 0 && currentLen + len > MSG_BUDGET) {
    messages.push(current);
    current = [];
    currentLen = 0;
  }
  current.push(block);
  currentLen += len;
}
if (current.length > 0) messages.push(current);

return messages.map((msgBlocks, i) => ({
  json: {
    blocksJson: JSON.stringify({ blocks: msgBlocks }),
    part: i + 1,
    totalParts: messages.length,
  },
}));
